package br.com.admeclesial.application.financeiro; import org.springframework.beans.factory.annotation.Autowired; import br.com.admeclesial.application.usuario.SegurancaOrganizacaoService; import br.com.admeclesial.domain.financeiro.*; import br.com.admeclesial.infrastructure.persistence.financeiro.*; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.math.BigDecimal; import java.time.LocalDate; import java.util.*; @Service public class ObrigacaoRepasseApplicationService { @Autowired SegurancaOrganizacaoService seguranca; final ObrigacaoRepasseRepository repo; final RegraRepasseRepository regra; final ContaAPagarRepository contas; final ParcelaAPagarRepository parcelas; public ObrigacaoRepasseApplicationService(ObrigacaoRepasseRepository r,RegraRepasseRepository rr,ContaAPagarRepository c,ParcelaAPagarRepository p){repo=r;regra=rr;contas=c;parcelas=p;} @Transactional public ObrigacaoRepasse gerar(ObrigacaoRepasseRequest r){var rg=regra.findByUuid(r.regraRepasseUuid()).orElseThrow(()->new IllegalArgumentException("Regra de repasse não encontrada."));if(seguranca!=null)seguranca.validarAcessoId(rg.getOrganizacaoOrigemId());BigDecimal liquida=r.valorBase().subtract(r.valorExclusoes());if(liquida.signum()<0)throw new IllegalArgumentException("Exclusões não podem superar a base.");if(r.valorBase().signum()<0||r.valorExclusoes().signum()<0)throw new IllegalArgumentException("Base e exclusões não podem ser negativas.");BigDecimal valor=rg.getTipoBase()==TipoBaseRepasse.VALOR_FIXO?rg.getValorFixo():liquida.multiply(rg.getPercentual()).divide(new BigDecimal("100"));if(valor.signum()<=0)throw new IllegalArgumentException("O valor do repasse deve ser maior que zero.");var e=new ObrigacaoRepasse();e.setRegraRepasseId(rg.getId());e.setCompetencia(r.competencia());e.setValorBase(r.valorBase());e.setValorExclusoes(r.valorExclusoes());e.setValorRepasse(valor);e.setDataVencimento(r.dataVencimento());e.setStatus(StatusObrigacaoRepasse.ABERTA);e.setObservacao(r.observacao());e=repo.save(e);var conta=new ContaAPagar();conta.setOrganizacaoEclesialId(rg.getOrganizacaoOrigemId());conta.setObrigacaoRepasseId(e.getId());conta.setDescricao("Repasse - competência " + r.competencia());conta.setDataEmissao(LocalDate.now());conta.setDataVencimento(r.dataVencimento());conta.setValorTotal(valor);conta.setStatus(StatusContaAPagar.ABERTA);conta=contas.save(conta);var parcela=new ParcelaAPagar();parcela.setContaAPagarId(conta.getId());parcela.setNumero(1);parcela.setVencimento(r.dataVencimento());parcela.setValor(valor);parcela.setStatus(StatusParcelaAPagar.ABERTA);parcelas.save(parcela);return e;} @Transactional(readOnly=true) public List<ObrigacaoRepasse> listar(){return repo.findAllByOrderByCompetenciaDesc().stream().filter(e->{var rg=regra.findById(e.getRegraRepasseId()).orElse(null);if(rg==null)return false;try{if(seguranca!=null)seguranca.validarAcessoId(rg.getOrganizacaoOrigemId());return true;}catch(org.springframework.security.access.AccessDeniedException ex){return false;}}).toList();}}